// Disposable offline probe: already-preprocessed patches, unchanged recognizer/parser.
#include "Coordinate/IdentifyWorldCoordinates/CoordinateCandidate.h"
#include "OfflineClockBoundary.h"
#include "CoordinateBuildFingerprint.generated.h"
#include <include/ocr_rec.h>
#include <nlohmann/json.hpp>
#include <opencv2/opencv.hpp>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <algorithm>
#include <chrono>
using Json=nlohmann::json;
Json Candidate(const CoordinateCandidate& c){return {{"x",c.x},{"y",c.y},{"z",c.z},{"score",c.modelScore},{"correction",c.correction},{"rawText",c.rawText}};}
Json Row(const std::string& id,const std::string& raw,float score,const std::vector<CoordinateCandidate>& candidates){
    Json all=Json::array(),selected=nullptr;for(const auto& c:candidates)all.push_back(Candidate(c));
    if(!candidates.empty())selected=Candidate(*std::max_element(candidates.begin(),candidates.end(),[](const auto&a,const auto&b){return a.modelScore<b.modelScore;}));
    return {{"id",id},{"rawText",raw},{"modelScore",score},{"selected",selected},{"candidates",all}};
}
int wmain(int argc,wchar_t**argv){try{
    if(argc!=4)throw std::runtime_error("Usage: model manifest report");
    std::filesystem::path model(argv[1]),manifest(argv[2]),output(argv[3]);
    if(std::filesystem::exists(output))throw std::runtime_error("Preserve previous report");
    auto config=YAML::LoadFile((model/"inference.yml").string());
    auto dict=config["PostProcess"]["character_dict"].as<std::vector<std::string>>();
    std::ifstream keys(model/"ppocr_keys.txt");std::vector<std::string> file;std::string line;
    while(std::getline(keys,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();file.push_back(line);}
    if(dict!=file)throw std::runtime_error("Dictionary mismatch");
    PaddleOCR::CRNNRecognizer rec(model.string(),false,0,4000,4,true,(model/"ppocr_keys.txt").string(),false,"fp32",1,48,320);
    std::ifstream stream(manifest);const auto inputs=Json::parse(stream).at("inputs");
    Json pipelines=Json::object();
    for(const auto& item:inputs){
        const auto id=item.at("id").get<std::string>();
        std::vector<std::vector<CoordinateCandidate>> parsed;
        std::vector<std::string> raw;std::vector<float> scores;
        for(const auto* variant:{"contrast","tophat","raw"}){
            auto image=cv::imread(item.at("images").at(variant).get<std::string>(),cv::IMREAD_COLOR);
            if(image.empty()||image.rows!=48)throw std::runtime_error("Invalid prepared patch");
            std::vector<std::string> texts(1);std::vector<float> conf(1);std::vector<double> times{0,0,0};
            rec.Run({image},texts,conf,times);raw.push_back(texts[0]);scores.push_back(conf[0]);
            auto prefix=CoordinatePrefixBeforeClock(texts[0]);auto text=prefix.value_or(texts[0]);
            auto candidates=CoordinateCandidateParser::Parse(text,conf[0]);parsed.push_back(candidates);
            auto row=Row(id,texts[0],conf[0],candidates);row["parsedText"]=text;row["clockBoundary"]=prefix?"verified-full-clock":"unchanged";
            pipelines[std::string("ppocr-")+variant+"-clock"].push_back(row);
        }
        auto cross=Row(id,raw[1],scores[1],CoordinateCandidateParser::Corroborate(parsed[1],parsed[0]));
        cross["witnessText"]=raw[0];pipelines["ppocr-corroborated-clock"].push_back(cross);
    }
    std::ofstream out(output);out<<Json{{"scope","Already-preprocessed image-gap patches. Existing parser/clock/XY corroboration, no position prior."},{"modelDirectory",model.string()},{"baseFingerprint",Json::parse(kCoordinateBuildFingerprint)},{"pipelines",pipelines}}.dump(2)<<'\n';
    if(!out)throw std::runtime_error("Cannot write report");
    std::cout<<"Replayed "<<inputs.size()<<" inputs\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}

