"""Pixel-only split. No labels, OCR results, neighboring frames or minimaps.
The input manifest supplies fixed already-selected source ROIs, not truths.
"""
from pathlib import Path
import json,hashlib
import cv2,numpy as np
ROOT=Path(__file__).resolve().parent;FT=ROOT.parent/'coordinate-finetune-20261015'
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
rule=read(ROOT/'rule-v1.json')
def locate(image):
    top,bottom=rule['rowRange'];left,right=rule['startRange']
    ink=(image[top:bottom]>rule['foregroundAbove']).sum(0)
    is_gap=ink<=rule['maxForegroundPerGapColumn']
    boundaries=np.flatnonzero(np.diff(np.r_[False,is_gap,False])).reshape(-1,2)
    gaps=[{'start':int(s),'end':int(e),'width':int(e-s)} for s,e in boundaries
          if left<=s<=right and rule['minGapWidth']<=e-s<=rule['maxGapWidth']]
    gaps.sort(key=lambda g:(-g['width'],g['start']))
    if not gaps:return {'cut':None,'reason':'no-eligible-gap','candidates':gaps}
    if len(gaps)>1 and gaps[0]['width']-gaps[1]['width']<rule['minWidthLeadOverRunnerUp']:
        return {'cut':None,'reason':'ambiguous-gaps','candidates':gaps}
    return {'cut':gaps[0]['start']+rule['contentMargin'],'reason':'unique-gap','candidates':gaps}
def main():
    manifest=ROOT/'gap-inputs.json'
    if manifest.exists():raise RuntimeError('Preserve previous prepared evidence')
    items=read(FT/'paired-v3/replay-inputs.json')['inputs']
    outdir=ROOT/'patches';outdir.mkdir(exist_ok=True);outputs=[]
    for item in items:
        ident=item['id'];paths={v:ROOT/'native-preprocessed'/f'{ident}.{v}.png' for v in ['contrast','tophat','raw']}
        decision=locate(cv2.imread(str(paths['tophat']),0))
        images={};original={};shapes={}
        for variant,path in paths.items():
            image=cv2.imread(str(path));assert image.shape==(48,892,3)
            original[variant]={'image':str(path),'sha256':sha(path)}
            if decision['cut'] is not None:
                patch=cv2.copyMakeBorder(image[:,:decision['cut']],0,0,0,rule['rightBlackBorder'],cv2.BORDER_CONSTANT,value=(0,0,0))
                target=outdir/f'{ident}.{variant}.png';assert cv2.imwrite(str(target),patch)
            else:target=path;patch=image
            images[variant]=str(target);shapes[variant]=list(patch.shape)
        outputs.append({'id':ident,'sourceId':item['sourceId'],'images':images,'decision':decision,'shapes':shapes,
            'sourceROI':item['image'],'sourceROISHA256':sha(Path(item['image'])),'original':original,
            'preparedSHA256':{v:sha(Path(p)) for v,p in images.items()}})
    assert len(outputs)==346
    manifest.write_text(json.dumps({'scope':'Label-blind gap probe, rule frozen before development evaluation','ruleSHA256':sha(ROOT/'rule-v1.json'),'inputs':outputs},ensure_ascii=False,indent=2)+'\n')
    print('Prepared',len(outputs),'split',sum(r['decision']['cut'] is not None for r in outputs),'fallback',sum(r['decision']['cut'] is None for r in outputs))
if __name__=='__main__':main()

