"""Truth is read only after the pixel-only preparation and native inference."""
from pathlib import Path
from collections import Counter
import json,hashlib
ROOT=Path(__file__).resolve().parent;FT=ROOT.parent/'coordinate-finetune-20261015';V3=FT/'paired-v3'
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
dev={f['id']:f for f in read(V3/'development-corpus.json')['frames']}
train={f['id']:f for f in read(V3/'training-pair-corpus.json')['frames']}
rows={r['id']:r for r in read(V3/'paired-manifest.json')['rows']}
prepared={x['id']:x for x in read(ROOT/'gap-inputs.json')['inputs']}
truth={**dev,**train};summaries=[];transitions=[];evidence=[]
def outcome(frame,pred):
    selected=pred['selected']
    if frame['state']=='unknown':return 'unknownReturned' if selected else 'unknownNoReturn'
    if frame['state']=='absent':return 'falsePositive' if selected else 'trueNegative'
    if selected is None:return 'miss'
    return 'correct' if all(frame['expected'][k]==selected[k] for k in 'xyz') else 'wrong'
for model,basepath,gappath in [('v2',ROOT/'baseline-v2.json',ROOT/'gap-v2.json'),('v3-routes',V3/'replay-pair-routes.json',ROOT/'gap-v3-routes.json')]:
    base=read(basepath);gap=read(gappath)
    evidence.append({'model':model,'baseline':str(basepath),'baselineSHA256':sha(basepath),'gap':str(gappath),'gapSHA256':sha(gappath)})
    for mode,afterrows in gap['pipelines'].items():
        before={p['id']:p for p in base['pipelines'][mode]};assert len(before)==346
        counts={}
        for p in afterrows:
            fid=p['id'].split('@')[0];f=truth[fid];a=outcome(f,p);b=outcome(f,before[p['id']]);cut=prepared[p['id']]['decision']['cut']
            groups=['trained-fit-only'] if fid in train else ['all-development']
            if fid in dev and fid in rows:groups.append(rows[fid]['sceneGroup'])
            if fid in dev and 776<=int(fid[-6:])<=787:groups.append('heldout-stationary-776-787')
            for group in groups:
                for condition,label in [('full',b),('gap',a)]:
                    c=counts.setdefault((group,condition),Counter());c['frames']+=1;c[label]+=1;c['splitApplied']+=cut is not None
            if a!=b:
                transitions.append({'model':model,'mode':mode,'id':fid,'trainedFitOnly':fid in train,'from':b,'to':a,'cut':cut,'expected':f['expected'],'before':before[p['id']],'after':p})
        for (group,condition),c in counts.items():
            summaries.append({'model':model,'mode':mode,'group':group,'condition':condition,**{k:c[k] for k in ['frames','splitApplied','correct','wrong','miss','falsePositive','trueNegative','unknownReturned','unknownNoReturn']}})
result={'scope':'170 same-session development XYZ,141 absent,8 unknown;27 training-source fit diagnostics separately. Frozen rule-v1, unchanged weights/parser. Not independent acceptance.',
    'newTrainingUpdates':0,'newDownloadsBytes':0,'productionChanged':False,'ruleSHA256':sha(ROOT/'rule-v1.json'),'sourceEvidence':evidence,
    'summary':summaries,'transitions':transitions}
(ROOT/'report.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
for s in summaries:
    if s['mode'] in ['ppocr-contrast-clock','ppocr-corroborated-clock'] and s['group'] in ['all-development','heldout-stationary-776-787','trained-fit-only','snow-pale-mixed']:
        print(s['model'],s['mode'],s['group'],s['condition'],s['correct'],s['wrong'],s['miss'],'FP',s['falsePositive'],'split',s['splitApplied'])

