from pathlib import Path
import json,importlib.util
ROOT=Path(__file__).resolve().parent;FT=ROOT.parent/'coordinate-finetune-20261015';V3=FT/'paired-v3'
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
truth={f['id']:f for name in ['development-corpus.json','training-pair-corpus.json'] for f in read(V3/name)['frames']}
train={f['id'] for f in read(V3/'training-pair-corpus.json')['frames']}
scenes={r['id']:r['sceneGroup'] for r in read(V3/'paired-manifest.json')['rows']}
reports=read(ROOT/'support-results.json');summary=[];additions=[]
for report in reports['reports']:
    groups={}
    for row in report['results']:
        fid=row['id'].split('@')[0];f=truth[fid];s=row['selected'];outcome='unknownReturned' if f['state']=='unknown' and s else 'unknownNoReturn' if f['state']=='unknown' else 'falsePositive' if f['state']=='absent' and s else 'trueNegative' if f['state']=='absent' else 'miss' if s is None else 'correct' if all(s[k]==f['expected'][k] for k in 'xyz') else 'wrong'
        memberships=['trained-fit-only'] if fid in train else ['all-development']
        if fid not in train and fid in scenes:memberships.append(scenes[fid])
        if fid not in train and 776<=int(fid[-6:])<=787:memberships.append('heldout-stationary-776-787')
        for group in memberships:
            c=groups.setdefault(group,{'frames':0,'correct':0,'wrong':0,'miss':0,'falsePositive':0,'trueNegative':0,'unknownReturned':0,'unknownNoReturn':0,'newSupportedReturn':0})
            c['frames']+=1;c[outcome]+=1;c['newSupportedReturn']+=row['supportProbe']['filledMissingReturn']
        if row['supportProbe']['filledMissingReturn']:additions.append({'model':report['model'],'id':fid,'trainedFitOnly':fid in train,'expected':f['expected'],'outcome':outcome,'row':row})
    summary.extend({'model':report['model'],'group':g,**c} for g,c in groups.items())
result={'scope':reports['scope'],'summary':summary,'additions':additions}
(ROOT/'support-report.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
for row in summary:
    if row['group'] in ['all-development','trained-fit-only','heldout-stationary-776-787','snow-pale-mixed']:print(row)
